package com.acme.catalog.controller; import com.acme.catalog.dto.ProductResponse; import com.acme.catalog.repository.ProductRepository; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/products") public class ProductController {private final ProductRepository repo;public ProductController(ProductRepository repo){this.repo=repo;}@GetMapping public java.util.List<ProductResponse> all(){return repo.findAll().stream().map(ProductResponse::of).toList();}@GetMapping("/{sku}") public ProductResponse one(@PathVariable String sku){return repo.findById(sku).filter(p->p.isActive()).map(ProductResponse::of).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Product not found"));}}
